{
 "command": "git ls-files services/notifier && cat services/notifier/*.py 2>/dev/null | head -200",
 "description": "List notifier files and show source"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-82wmo4yd/ledgerline/services/notifier && for f in README.md notifier/*.py pyproject.toml tests/*.py; do echo \"=== $f\"; cat $f; done; ls templates 2>/dev/null; cat ../../Makefile 2>/dev/null; ls ../../",
 "description": "Show notifier sources, tests, config"
}

{
 "pattern": "sink|integration|markers|MAIL_",
 "path": "/tmp/mte-bf-notifier-sandbox-82wmo4yd/ledgerline",
 "output_mode": "content"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-82wmo4yd/ledgerline && cat pyproject.toml tests/test_payments.py; ls tests docs",
 "description": "Show root pytest config and integration test example"
}

{
 "command": "cat docs/testing.md docs/dev-setup.md; ls docs/ops; grep -ril \"mail\\|inbox\" docs",
 "description": "Read testing docs and search for mail/inbox notes"
}

{
 "replace_all": false,
 "file_path": "/tmp/mte-bf-notifier-sandbox-82wmo4yd/ledgerline/services/notifier/pyproject.toml",
 "old_string": "dev = [\"pytest>=8.0\"]",
 "new_string": "dev = [\"pytest>=8.0\"]\n\n[tool.pytest.ini_options]\nmarkers = [\n    \"integration: talks to the email provider sandbox over the network\",\n]"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-82wmo4yd/ledgerline/services/notifier && python -m pytest --import-mode=importlib tests -q -rs 2>&1 | tail -5",
 "description": "Run notifier tests"
}
